Single Page Application (SPA) / Mobile C.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Single Page Application (SPA) / Mobile Client container

Container_Boundary(spa_mobile_client, "Single Page Application (SPA) / Mobile Client") {
    Component(User_Interface_View, "User Interface View", "React, Angular, or Mobile Native", "Provides the visual interface for browsing catalogues, checking out, writing reviews, and viewing recommendations.")
    Component(State_Management_Offline_Storage, "State Management & Offline Storage", "Redux Persist / React Query", "Manages application state and provides offline caching capabilities for the client application.")
}

Rel(User_Interface_View, State_Management_Offline_Storage, "Reads and writes local state and cached data")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge_Router_and_Reverse_Proxy, "Edge Router and Reverse Proxy", "AWS API Gateway / Reverse Proxy", "Centralizes edge routing, HTTPS termination, and traffic distribution across multi-region deployments.")
    Component(Authentication_and_Security_Filter, "Authentication and Security Filter", "OAuth2 / JWT / AWS WAF", "Handles user authentication, rate limiting, and request validation at the edge.")
    Component(Circuit_Breaker_and_Load_Balancer, "Circuit Breaker and Load Balancer", "Spring Cloud Circuit Breaker / Resilience4j", "Ensures fault tolerance and graceful degradation when routing traffic to backend microservices.")
}

Rel(Edge_Router_and_Reverse_Proxy, Authentication_and_Security_Filter, "Passes incoming requests for security inspection and token validation")
Rel(Authentication_and_Security_Filter, Circuit_Breaker_and_Load_Balancer, "Forwards validated requests for backend routing")

@enduml

Asynchronous Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(asynchronous_message_broker, "Asynchronous Message Broker") {
    Component(Event_Publisher, "Event Publisher", "AWS SNS", "Publishes asynchronous domain events from microservices to the messaging infrastructure.")
    Component(Event_Consumer, "Event Consumer", "AWS SQS", "Queues and delivers asynchronous messages to subscribed microservices for processing.")
    Component(Event_Archive, "Event Archive", "AWS Kinesis / SQS Archive", "Stores historical events for event replay, auditing, and compliance purposes.")
}

Rel(Event_Publisher, Event_Consumer, "Routes published events to appropriate message queues")
Rel(Event_Consumer, Event_Archive, "Persists processed event streams for replay and analytics")

@enduml

Compliance/User Data Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(compliance_user_data_container, "Compliance/User Data Container") {
    Component(UserDataRepository, "User Data Repository", "AWS RDS / Aurora", "Segregated database storing sensitive consumer information with multi-region replication and database-per-service isolation.")
    Component(CryptographicErasureEngine, "Cryptographic Erasure Engine", "AWS KMS", "Manages cryptographic keys and executes cryptographic erasure to meet GDPR and CCPA mandates.")
}

Rel(CryptographicErasureEngine, UserDataRepository, "Provides cryptographic keys and encryption-at-rest for sensitive records", "HTTPS")

@enduml
